import java.util.Scanner;
public class VendingMachine1
{
	public static void main(String[] args)
	{
		//Paso 1: Definir las constantes que necesitamos para este programa
		final int PENNIES_PER_DOLLAR = 100;
		final int PENNIES_PER_QUARTER = 25;
		//Paso 2: Leer el valor del billete y el precio del articulo
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el valor del billete en dolares (1 = billete de $1, 5 = billete de $5, etc.): ");
		int billValue = scan.nextInt();
		System.out.println("Ingrese el precio del articulo en centavos: ");
		int itemPrice = scan.nextInt();
		scan.close();
		//Paso 3: Calcular el cambio a devolver
		int changeDue = PENNIES_PER_DOLLAR * billValue - itemPrice;
		//Paso 4: Calcular el numero de dolares y actualizar el cambio restante despues de quitar los dolares
		int dollars = changeDue / PENNIES_PER_DOLLAR;
		changeDue = changeDue % PENNIES_PER_DOLLAR;
		//Paso 5: Calcular el numero de monedas de 25 centavos en el cambio restante
		int quarters = changeDue / PENNIES_PER_QUARTER;
		//Paso 6: Mostrar el resultado
		System.out.println("Su cambio consiste en:"); 
		System.out.println(dollars + " dolares");
		System.out.println(quarters + " monedas de 25 centavos");
	}
}

